-- Append-only homepage presentation duty. Original cycle, budget, receipts and images remain unchanged.
CREATE TABLE tower_autonomy_extensions(id TEXT PRIMARY KEY,cycle_id TEXT NOT NULL UNIQUE REFERENCES tower_autonomy_cycles(id),obligation_version INTEGER NOT NULL CHECK(obligation_version=1),capability TEXT NOT NULL CHECK(capability='style-public-lobby-v1'),generation_id TEXT NOT NULL,appearance_revision INTEGER NOT NULL CHECK(appearance_revision>0),original_budget_micro INTEGER NOT NULL CHECK(original_budget_micro BETWEEN 1 AND 10000000),starts_at TEXT NOT NULL CHECK(starts_at='2026-10-31T07:00:00.000Z'),ends_at TEXT NOT NULL CHECK(ends_at='2026-11-01T07:00:00.000Z'),state TEXT NOT NULL CHECK(state IN ('plan','render-0','render-1','render-2','render-3','verify','tool-ack','audit','activate','selfreview','complete','blocked')),step_seq INTEGER NOT NULL DEFAULT 0,lease_until TEXT,repair INTEGER NOT NULL DEFAULT 0 CHECK(repair IN (0,1)),artifact_id TEXT,tool_json TEXT CHECK(tool_json IS NULL OR json_valid(tool_json)),evidence_json TEXT CHECK(evidence_json IS NULL OR json_valid(evidence_json)),audit_json TEXT CHECK(audit_json IS NULL OR json_valid(audit_json)),review_json TEXT CHECK(review_json IS NULL OR json_valid(review_json)),error_code TEXT,outcome TEXT NOT NULL DEFAULT 'pending' CHECK(outcome IN ('pending','pass','blocked')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE tower_theme_artifacts(id TEXT PRIMARY KEY,extension_id TEXT NOT NULL REFERENCES tower_autonomy_extensions(id),repair INTEGER NOT NULL CHECK(repair IN (0,1)),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json) AND length(manifest_json)<5000),sha256 TEXT NOT NULL CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^0-9a-f]*'),renderer_version TEXT NOT NULL CHECK(renderer_version='lobby-theme-v1'),plan_call_id TEXT NOT NULL REFERENCES tower_autonomy_calls(id),created_at TEXT NOT NULL,UNIQUE(extension_id,repair));
CREATE TABLE tower_theme_current(id INTEGER PRIMARY KEY CHECK(id=1),artifact_id TEXT NOT NULL REFERENCES tower_theme_artifacts(id),extension_id TEXT NOT NULL REFERENCES tower_autonomy_extensions(id),generation_id TEXT NOT NULL,appearance_revision INTEGER NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL);
CREATE TRIGGER tower_theme_extension_delete BEFORE DELETE ON tower_autonomy_extensions BEGIN SELECT RAISE(ABORT,'theme_permanent'); END;
CREATE TRIGGER tower_theme_extension_replace BEFORE INSERT ON tower_autonomy_extensions WHEN EXISTS(SELECT 1 FROM tower_autonomy_extensions WHERE id=NEW.id OR cycle_id=NEW.cycle_id) BEGIN SELECT RAISE(ABORT,'theme_immutable'); END;
CREATE TRIGGER tower_theme_artifact_delete BEFORE DELETE ON tower_theme_artifacts BEGIN SELECT RAISE(ABORT,'theme_permanent'); END;
CREATE TRIGGER tower_theme_artifact_replace BEFORE INSERT ON tower_theme_artifacts WHEN EXISTS(SELECT 1 FROM tower_theme_artifacts WHERE id=NEW.id OR (extension_id=NEW.extension_id AND repair=NEW.repair)) BEGIN SELECT RAISE(ABORT,'theme_immutable'); END;
CREATE TRIGGER tower_theme_artifact_update BEFORE UPDATE ON tower_theme_artifacts BEGIN SELECT RAISE(ABORT,'theme_immutable'); END;
CREATE TRIGGER tower_theme_extension_binding BEFORE UPDATE ON tower_autonomy_extensions WHEN NEW.id!=OLD.id OR NEW.cycle_id!=OLD.cycle_id OR NEW.obligation_version!=OLD.obligation_version OR NEW.capability!=OLD.capability OR NEW.generation_id!=OLD.generation_id OR NEW.appearance_revision!=OLD.appearance_revision OR NEW.original_budget_micro!=OLD.original_budget_micro OR NEW.starts_at!=OLD.starts_at OR NEW.ends_at!=OLD.ends_at OR NEW.created_at!=OLD.created_at OR NEW.repair<OLD.repair OR NEW.repair>OLD.repair+1 OR OLD.state IN ('complete','blocked') BEGIN SELECT RAISE(ABORT,'theme_binding_immutable'); END;
CREATE TRIGGER tower_theme_extension_authority BEFORE INSERT ON tower_autonomy_extensions WHEN COALESCE((NEW.id=NEW.cycle_id||':public-lobby-theme-v1' AND NEW.state='plan' AND NEW.repair=0 AND NEW.step_seq=0 AND NEW.lease_until IS NULL AND NEW.artifact_id IS NULL AND EXISTS(SELECT 1 FROM (SELECT NEW.cycle_id cycle_id,NEW.original_budget_micro original_budget_micro,NEW.generation_id generation_id,NEW.appearance_revision appearance_revision,NEW.starts_at starts_at,NEW.ends_at ends_at) e WHERE (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND e.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND e.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM tower_autonomy_current p JOIN tower_autonomy_cycles c ON c.id=p.cycle_id JOIN tower_autonomy_authorizations a ON a.cycle_id=c.id JOIN tower_autonomy_task_anchors t ON t.cycle_id=c.id WHERE c.id=e.cycle_id AND c.state='complete' AND c.outcome='pass' AND c.repair=0 AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND c.budget_micro=e.original_budget_micro AND a.budget_micro=c.budget_micro AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND p.generation_id=e.generation_id AND p.revision=e.appearance_revision AND p.starts_at=e.starts_at AND p.ends_at=e.ends_at AND EXISTS(SELECT 1 FROM tower_autonomy_calls x WHERE x.id=json_extract(c.audit_json,'$.callId') AND x.state='received' AND x.cycle_id=c.id AND x.purpose='independent-task-audit' AND x.model='muse-spark-1.3')) AND NOT EXISTS(SELECT 1 FROM tower_autonomy_calls WHERE cycle_id=e.cycle_id AND state IN ('unknown','dispatching')) AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE cycle_id=e.cycle_id)+2100000<=e.original_budget_micro) AND EXISTS(SELECT 1 FROM tower_autonomy_events v WHERE v.id=NEW.id||':mandate' AND v.cycle_id=NEW.cycle_id AND v.kind='lobby-theme-mandate-enabled' AND v.created_at=NEW.created_at AND json_extract(v.detail_json,'$.capability')=NEW.capability)),0)!=1 BEGIN SELECT RAISE(ABORT,'theme_authority_denied'); END;
CREATE TRIGGER tower_theme_extension_transition BEFORE UPDATE ON tower_autonomy_extensions WHEN NEW.state!=OLD.state AND (NEW.step_seq!=OLD.step_seq+1 OR NEW.lease_until IS NOT NULL OR (NEW.state NOT IN ('selfreview','blocked') AND (OLD.lease_until IS NULL OR OLD.lease_until<=strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM tower_autonomy_extensions e WHERE e.id=OLD.id AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND e.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND e.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM tower_autonomy_current p JOIN tower_autonomy_cycles c ON c.id=p.cycle_id JOIN tower_autonomy_authorizations a ON a.cycle_id=c.id JOIN tower_autonomy_task_anchors t ON t.cycle_id=c.id WHERE c.id=e.cycle_id AND c.state='complete' AND c.outcome='pass' AND c.repair=0 AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND c.budget_micro=e.original_budget_micro AND a.budget_micro=c.budget_micro AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND p.generation_id=e.generation_id AND p.revision=e.appearance_revision AND p.starts_at=e.starts_at AND p.ends_at=e.ends_at AND EXISTS(SELECT 1 FROM tower_autonomy_calls x WHERE x.id=json_extract(c.audit_json,'$.callId') AND x.state='received' AND x.cycle_id=c.id AND x.purpose='independent-task-audit' AND x.model='muse-spark-1.3')))))) BEGIN SELECT RAISE(ABORT,'theme_transition_denied'); END;
CREATE TRIGGER tower_theme_call_scope BEFORE INSERT ON tower_autonomy_calls WHEN NEW.purpose LIKE 'lobby-theme-v1:%' AND COALESCE((EXISTS(SELECT 1 FROM tower_autonomy_extensions e WHERE e.cycle_id=NEW.cycle_id AND e.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND NEW.step_key=e.cycle_id||':'||e.step_seq||':'||NEW.purpose AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND (NEW.purpose='lobby-theme-v1:'||e.state OR NEW.purpose='lobby-theme-v1:'||e.state||':input-token-count') AND ((e.state='selfreview' AND NEW.model='muse-spark-1.3') OR (e.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND e.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM tower_autonomy_current p JOIN tower_autonomy_cycles c ON c.id=p.cycle_id JOIN tower_autonomy_authorizations a ON a.cycle_id=c.id JOIN tower_autonomy_task_anchors t ON t.cycle_id=c.id WHERE c.id=e.cycle_id AND c.state='complete' AND c.outcome='pass' AND c.repair=0 AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND c.budget_micro=e.original_budget_micro AND a.budget_micro=c.budget_micro AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND p.generation_id=e.generation_id AND p.revision=e.appearance_revision AND p.starts_at=e.starts_at AND p.ends_at=e.ends_at AND EXISTS(SELECT 1 FROM tower_autonomy_calls x WHERE x.id=json_extract(c.audit_json,'$.callId') AND x.state='received' AND x.cycle_id=c.id AND x.purpose='independent-task-audit' AND x.model='muse-spark-1.3')) AND NOT EXISTS(SELECT 1 FROM tower_autonomy_calls x WHERE x.cycle_id=e.cycle_id AND x.state IN ('unknown','dispatching')) AND ((e.state IN ('plan','tool-ack','audit') AND NEW.model='muse-spark-1.3') OR (e.state IN ('render-0','render-1','render-2','render-3') AND NEW.model='tool:browser-screenshot' AND NEW.reserved_micro=90000)))))),0)!=1 BEGIN SELECT RAISE(ABORT,'theme_dispatch_denied'); END;
CREATE TRIGGER tower_theme_artifact_provenance BEFORE INSERT ON tower_theme_artifacts WHEN COALESCE((EXISTS(SELECT 1 FROM tower_autonomy_extensions e JOIN tower_autonomy_calls p ON p.id=NEW.plan_call_id WHERE e.id=NEW.extension_id AND e.state='plan' AND e.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND e.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND e.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM tower_autonomy_current p JOIN tower_autonomy_cycles c ON c.id=p.cycle_id JOIN tower_autonomy_authorizations a ON a.cycle_id=c.id JOIN tower_autonomy_task_anchors t ON t.cycle_id=c.id WHERE c.id=e.cycle_id AND c.state='complete' AND c.outcome='pass' AND c.repair=0 AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND c.budget_micro=e.original_budget_micro AND a.budget_micro=c.budget_micro AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND p.generation_id=e.generation_id AND p.revision=e.appearance_revision AND p.starts_at=e.starts_at AND p.ends_at=e.ends_at AND EXISTS(SELECT 1 FROM tower_autonomy_calls x WHERE x.id=json_extract(c.audit_json,'$.callId') AND x.state='received' AND x.cycle_id=c.id AND x.purpose='independent-task-audit' AND x.model='muse-spark-1.3')) AND p.cycle_id=e.cycle_id AND p.purpose='lobby-theme-v1:plan' AND p.state='received' AND p.model='muse-spark-1.3' AND p.step_key=e.cycle_id||':'||e.step_seq||':lobby-theme-v1:plan' AND NEW.repair=e.repair AND NEW.id=e.id||':r'||e.repair) AND json_extract(NEW.manifest_json,'$.version')=1 AND (SELECT count(*) FROM json_each(NEW.manifest_json))=5 AND (SELECT count(*) FROM json_each(NEW.manifest_json,'$.day'))=9 AND (SELECT count(*) FROM json_each(NEW.manifest_json,'$.night'))=9 AND NOT EXISTS(SELECT 1 FROM json_each(NEW.manifest_json) WHERE key NOT IN ('version','day','night','layout','decoration'))),0)!=1 BEGIN SELECT RAISE(ABORT,'theme_artifact_provenance'); END;
CREATE TRIGGER tower_theme_current_insert BEFORE INSERT ON tower_theme_current WHEN EXISTS(SELECT 1 FROM tower_theme_current WHERE id=NEW.id) OR NEW.revision!=1 OR NOT (EXISTS(SELECT 1 FROM tower_autonomy_extensions e JOIN tower_theme_artifacts a ON a.id=e.artifact_id JOIN tower_autonomy_calls q ON q.id=json_extract(e.audit_json,'$.callId') WHERE e.id=NEW.extension_id AND e.state='activate' AND e.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND e.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND e.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM tower_autonomy_current p JOIN tower_autonomy_cycles c ON c.id=p.cycle_id JOIN tower_autonomy_authorizations a ON a.cycle_id=c.id JOIN tower_autonomy_task_anchors t ON t.cycle_id=c.id WHERE c.id=e.cycle_id AND c.state='complete' AND c.outcome='pass' AND c.repair=0 AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND c.budget_micro=e.original_budget_micro AND a.budget_micro=c.budget_micro AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND p.generation_id=e.generation_id AND p.revision=e.appearance_revision AND p.starts_at=e.starts_at AND p.ends_at=e.ends_at AND EXISTS(SELECT 1 FROM tower_autonomy_calls x WHERE x.id=json_extract(c.audit_json,'$.callId') AND x.state='received' AND x.cycle_id=c.id AND x.purpose='independent-task-audit' AND x.model='muse-spark-1.3')) AND NOT EXISTS(SELECT 1 FROM tower_autonomy_calls WHERE cycle_id=e.cycle_id AND state IN ('unknown','dispatching')) AND a.id=NEW.artifact_id AND a.extension_id=e.id AND a.renderer_version='lobby-theme-v1' AND e.generation_id=NEW.generation_id AND e.appearance_revision=NEW.appearance_revision AND NEW.starts_at=e.starts_at AND NEW.ends_at=e.ends_at AND json_extract(e.evidence_json,'$.verified')=1 AND json_extract(e.evidence_json,'$.manifestHash')=a.sha256 AND (SELECT count(*) FROM json_each(e.evidence_json,'$.screenshots') s JOIN tower_autonomy_calls p ON p.id=json_extract(s.value,'$.callId') WHERE p.cycle_id=e.cycle_id AND p.model='tool:browser-screenshot' AND p.state='received' AND p.actual_micro IS NOT NULL AND p.actual_micro<=p.reserved_micro AND json_extract(s.value,'$.artifactId')=a.id AND p.purpose='lobby-theme-v1:render-'||s.key)=4 AND json_extract(e.audit_json,'$.verdict')='PASS' AND json_extract(e.audit_json,'$.manifestHash')=a.sha256 AND q.cycle_id=e.cycle_id AND q.purpose='lobby-theme-v1:audit' AND q.state='received' AND q.model='muse-spark-1.3')) BEGIN SELECT RAISE(ABORT,'theme_activation_denied'); END;
CREATE TRIGGER tower_theme_current_update BEFORE UPDATE ON tower_theme_current WHEN NEW.revision!=OLD.revision+1 OR NOT (EXISTS(SELECT 1 FROM tower_autonomy_extensions e JOIN tower_theme_artifacts a ON a.id=e.artifact_id JOIN tower_autonomy_calls q ON q.id=json_extract(e.audit_json,'$.callId') WHERE e.id=NEW.extension_id AND e.state='activate' AND e.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND e.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND e.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM tower_autonomy_current p JOIN tower_autonomy_cycles c ON c.id=p.cycle_id JOIN tower_autonomy_authorizations a ON a.cycle_id=c.id JOIN tower_autonomy_task_anchors t ON t.cycle_id=c.id WHERE c.id=e.cycle_id AND c.state='complete' AND c.outcome='pass' AND c.repair=0 AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND c.budget_micro=e.original_budget_micro AND a.budget_micro=c.budget_micro AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND p.generation_id=e.generation_id AND p.revision=e.appearance_revision AND p.starts_at=e.starts_at AND p.ends_at=e.ends_at AND EXISTS(SELECT 1 FROM tower_autonomy_calls x WHERE x.id=json_extract(c.audit_json,'$.callId') AND x.state='received' AND x.cycle_id=c.id AND x.purpose='independent-task-audit' AND x.model='muse-spark-1.3')) AND NOT EXISTS(SELECT 1 FROM tower_autonomy_calls WHERE cycle_id=e.cycle_id AND state IN ('unknown','dispatching')) AND a.id=NEW.artifact_id AND a.extension_id=e.id AND a.renderer_version='lobby-theme-v1' AND e.generation_id=NEW.generation_id AND e.appearance_revision=NEW.appearance_revision AND NEW.starts_at=e.starts_at AND NEW.ends_at=e.ends_at AND json_extract(e.evidence_json,'$.verified')=1 AND json_extract(e.evidence_json,'$.manifestHash')=a.sha256 AND (SELECT count(*) FROM json_each(e.evidence_json,'$.screenshots') s JOIN tower_autonomy_calls p ON p.id=json_extract(s.value,'$.callId') WHERE p.cycle_id=e.cycle_id AND p.model='tool:browser-screenshot' AND p.state='received' AND p.actual_micro IS NOT NULL AND p.actual_micro<=p.reserved_micro AND json_extract(s.value,'$.artifactId')=a.id AND p.purpose='lobby-theme-v1:render-'||s.key)=4 AND json_extract(e.audit_json,'$.verdict')='PASS' AND json_extract(e.audit_json,'$.manifestHash')=a.sha256 AND q.cycle_id=e.cycle_id AND q.purpose='lobby-theme-v1:audit' AND q.state='received' AND q.model='muse-spark-1.3')) BEGIN SELECT RAISE(ABORT,'theme_activation_denied'); END;
CREATE TRIGGER tower_theme_current_delete BEFORE DELETE ON tower_theme_current BEGIN SELECT RAISE(ABORT,'theme_current_permanent'); END;
